        if (covers.isEmpty()) return false;
        int[] steps = {OVERLAP_STEPS};
        List<Integer> positions = new ArrayList<Integer>();
        List<List<Set<FType>>> parts = new ArrayList<List<Set<FType>>>();
        long combinations = 1;
